// L'item arrive dans l'environnement : son identifiant, et son contenu en JSON.
// Les deux variables sont absentes quand l'exécution ne vient pas d'une file —
// c'est ainsi qu'on distingue les deux situations.
const id = process.env.ROTA_WORK_ITEM_ID
if (!id) {
  console.error("lancé hors file : rien à faire")
  process.exit(1)
}

const { image, largeur = 640 } = JSON.parse(process.env.ROTA_WORK_INPUT)
console.log(`item ${id} — ${image} en ${largeur} px`)

if (!(await Bun.file(image).exists())) {
  // Sortie non nulle : Rota compte la tentative, met l'item de côté le temps du
  // backoff, puis abandonne au plafond. Rien à écrire dans la file nous-mêmes.
  console.error(`introuvable : ${image}`)
  process.exit(1)
}

const sortie = image.replace(/(\.[^.]+)$/, `.${largeur}$1`)
const { exitCode, stderr } = Bun.spawnSync(['sips', '-Z', String(largeur), image, '--out', sortie])
if (exitCode !== 0) {
  console.error(stderr.toString())
  process.exit(exitCode)
}

// La dernière sortie est gardée comme résultat de l'item, visible dans la vue
// Work sans avoir à ouvrir l'exécution.
console.log(`écrit ${sortie}`)
